let products=[],filter='Tous',query='';const grid=document.querySelector('#products'),dialog=document.querySelector('#detail');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function packshot(p,lazy=true){return `<div class="packshot ${p.package}" role="img" aria-label="عرض ${esc(p.name)}, ${p.size}"><img class="package-base" src="assets/package-${p.package}.webp" alt="" ${lazy?'loading="lazy"':''}><div class="package-label"><img src="${p.front}" alt="ملصق ${esc(p.name)}" ${lazy?'loading="lazy"':''}></div><span class="package-volume">${p.size}</span></div>`;}
function render(){const list=products.map((p,i)=>({...p,i})).filter(p=>(filter==='Tous'||p.cat===filter)&&(p.name+' '+p.sub+' '+p.cat+' '+p.catAr).toLocaleLowerCase('fr').includes(query));grid.innerHTML=list.map(p=>`<article class="card"><button class="card-image" data-open="${p.i}" aria-label="اكتشفوا ${esc(p.name)}"><span class="product-state">${p.state}</span>${packshot(p)}</button><div class="card-content"><p class="category">${p.catAr}</p><h3>${p.name}</h3><p class="card-sub">${p.sub}</p><p class="card-desc">${p.desc}</p><div class="card-basis"><span>أساس التركيبة</span><p>${p.basis}</p></div><div class="card-meta"><span>${p.uses[0][0]}</span><span>${p.size}</span></div><button class="product-action" data-open="${p.i}">عرض بطاقة المنتج <span>→</span></button></div></article>`).join('');document.querySelector('#empty').hidden=list.length>0;document.querySelector('#result-count').textContent=list.length+' منتجات';}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(x=>{const on=x.dataset.filter===value;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});render();}
function openProduct(i){const p=products[i];if(!p)return;document.querySelector('#detail-content').innerHTML=`<div class="detail-grid"><div class="detail-visual">${packshot(p,false)}<span>${p.size} · ${p.state}</span><a href="${p.pdf}" target="_blank" rel="noopener">الملصق الأصلي الكامل PDF ←</a></div><div class="detail-summary"><p class="eyebrow">BIOJOUD / ${p.catAr}</p><h2 id="product-title" dir="ltr">${p.name}</h2><h3>${p.sub}</h3><p>${p.desc}</p><div class="detail-buttons"><button class="button gold" data-quote="${i}">طلب عرض سعر ←</button><a class="button outline" href="${p.pdf}" target="_blank" rel="noopener">تحميل الملصق PDF ↓</a><button class="share-product button outline" data-share="${i}">مشاركة بطاقة المنتج</button></div><p class="source-note">معلومات مستمدة من ملصق BIOJOUD. الملصق الأصلي هو المرجع الكامل لشروط الاستعمال.</p></div></div><div class="technical"><section><p class="eyebrow">01 / التركيبة</p><h3>مكونات المنتج</h3><table><tbody>${p.composition.map(r=>`<tr><th scope="row">${r[0]}</th><td dir="auto">${r[1]}</td></tr>`).join('')}</tbody></table></section><section><p class="eyebrow">02 / التطبيق</p><h3>طرق الاستعمال والجرعات</h3>${p.uses.map(r=>`<div class="dose"><div><b>${r[0]}</b><strong dir="auto">${r[1]}</strong></div><p>${r[2]}</p></div>`).join('')}<p class="source-note">الجرعات من الملصق وتضبط مع BIOJOUD حسب المحصول وظروف التطبيق. L = لتر، ml = مل، kg = كيلوغرام، ha = هكتار، p/v = وزن/حجم.</p></section><section><p class="eyebrow">03 / معلومات تقنية</p><h3>المحاصيل والتخزين والتوافق</h3><p>يرجى الرجوع إلى الملصق الأصلي للاطلاع على المحاصيل المعنية والخصائص الفيزيائية وشروط التخزين والتوافق الخاصة بهذا المنتج.</p><a class="button outline" href="index.html?produit=${encodeURIComponent(p.name)}">عرض البطاقة التقنية الكاملة بالفرنسية ←</a></section></div><div class="safety"><strong>احتياطات الاستعمال</strong><p>للاستعمال الزراعي. يحفظ بعيدا عن متناول الأطفال. تجنب ملامسة العينين والجلد. ارتد معدات الوقاية المحددة على الملصق. لا يبتلع. اقرأ جميع الاحتياطات والقيود قبل الاستعمال.</p></div><details class="label-preview"><summary>عرض الملصق الأصلي</summary><a href="${p.pdf}" target="_blank" rel="noopener"><img src="${p.label}" alt="الملصق الأصلي ${p.name}" loading="lazy"></a></details>`;dialog.showModal();dialog.scrollTop=0;}
fetch('products-ar.json?v=7').then(r=>{if(!r.ok)throw Error();return r.json()}).then(p=>{products=p;render();const select=document.querySelector('#contact-product');p.forEach(x=>{const o=document.createElement('option');o.value=x.name;o.textContent=x.name+' — '+x.size;select.append(o)});setFilter('Tous');const key=new URLSearchParams(location.search).get('produit');const idx=products.findIndex(x=>x.name===key);if(idx>=0)openProduct(idx);const request=new URLSearchParams(location.search).get('demande');if(request&&products.some(x=>x.name===request)){select.value=request;document.querySelector('#contact').scrollIntoView()}}).catch(()=>grid.innerHTML='<p>الكتالوج غير متاح حاليا. يرجى التواصل عبر البريد للحصول على البطاقات.</p>');
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open)openProduct(+open.dataset.open);const b=e.target.closest('[data-filter]');if(b)setFilter(b.dataset.filter);const link=e.target.closest('[data-category-link]');if(link)setFilter(link.dataset.categoryLink);const quote=e.target.closest('[data-quote]');if(quote){document.querySelector('#contact-product').value=products[+quote.dataset.quote].name;dialog.close();document.querySelector('#contact').scrollIntoView({behavior:'smooth'});document.querySelector('[name="nom"]').focus({preventScroll:true})}});
document.querySelector('.search input').addEventListener('input',e=>{query=e.target.value.trim().toLocaleLowerCase('fr');render()});document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});const menu=document.querySelector('.menu');menu.onclick=()=>{const n=document.querySelector('nav');n.classList.toggle('open');menu.setAttribute('aria-expanded',n.classList.contains('open'))};document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const subject='تواصل BIOJOUD — '+(d.get('produit')||'BIOJOUD');const body='مرحبا BIOJOUD،\n\n'+d.get('message')+'\n\nالاسم: '+d.get('nom')+'\nالبريد: '+d.get('email')+'\nالمنتج: '+(d.get('produit')||'طلب استشارة')+'\n\nشكرا.';window.location.href='mailto:biojoudmaroc@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#contact-status').textContent='تم تحضير الطلب. أرسلوه من تطبيق البريد. إذا لم يفتح، راسلوا biojoudmaroc@gmail.com مباشرة.';});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-share]');if(!b)return;const u=new URL(location.href);u.searchParams.set('produit',products[+b.dataset.share].name);u.hash='';try{await navigator.clipboard.writeText(u.href);b.textContent='تم نسخ الرابط';}catch{b.textContent='نسخ الرابط';const a=document.createElement('input');a.value=u.href;a.readOnly=true;b.after(a);a.select();}});
